/* From Uiverse.io by alexmaracinaru - Tags: simple, green, card, quote, monochromatic */
.__UIV_SCOPE__ .card {
  width: 190px;
  height: 264px;
  background: rgb(183, 226, 25);
  font-family: inherit;
  position: relative;
  border-radius: 8px;
}

.__UIV_SCOPE__ .quote {
  color: rgb(223, 248, 134);
  padding-left: 30px;
  position: relative;
}

.__UIV_SCOPE__ .card-name {
  text-transform: uppercase;
  font-weight: 700;
  color: rgb(127, 155, 29);
  padding: 35px;
  line-height: 23px;
}

.__UIV_SCOPE__ .body-text {
  font-size: 20px;
  font-weight: 900;
  padding: 60px 40px 0;
  color: #465512;
  position: absolute;
  top: 40px;
  left: 1px;
  line-height: 23px;
}

.__UIV_SCOPE__ .author {
  margin-top: 5px;
  opacity: 0;
  transition: 0.5s;
}

.__UIV_SCOPE__ .card:hover .author {
  opacity: 1;
}

.__UIV_SCOPE__ .pic {
  width: 50px;
  height: 50px;
  background-color: rgb(158, 196, 21);
  border-radius: 50%;
}

.__UIV_SCOPE__ .author-container {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .author {
  font-weight: 700;
  color: rgb(127, 155, 29);
  padding-left: 30px;
}

.__UIV_SCOPE__ .card .author svg {
  display: inline;
  font-size: 12px;
  color: rgba(128, 155, 29, 0.452);
}
